def main():
    N = int(input())
    beans = [list(map(int, input().split())) for _ in range(N)]

    # Dictionary to store the maximum deliciousness for each color
    color_max_deliciousness = {}

    for deliciousness, color in beans:
        if color in color_max_deliciousness:
            color_max_deliciousness[color] = max(color_max_deliciousness[color], deliciousness)
        else:
            color_max_deliciousness[color] = deliciousness

    # Find the maximum of the minimum deliciousness values
    max_min_deliciousness = max(color_max_deliciousness.values())

    print(max_min_deliciousness)
